import { Button } from '@refy-design/web';
import { ProgressBar } from '@refy-design/web';
import type { ComponentProps } from 'react';
import { useState } from 'react';
export function Example() {
  const args: Pick<ComponentProps<typeof ProgressBar>, 'value' | 'tone' | 'size'> = {
    value: 49,
    tone: 'primary',
    size: 'md',
  };
  const [value, setValue] = useState(20);
  return (
    <div style={{ width: 320, display: 'flex', flexDirection: 'column', gap: 12 }}>
      <ProgressBar {...args} value={value} />
      <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
        <Button
          size="sm"
          variant="secondary"
          onClick={() => setValue((v) => Math.max(0, v - 25))}
        >
          −25
        </Button>
        <Button
          size="sm"
          variant="secondary"
          onClick={() => setValue((v) => Math.min(100, v + 25))}
        >
          +25
        </Button>
        <code
          style={{
            fontFamily: 'var(--font-mono)',
            fontSize: 12,
            color: 'var(--ink-2)',
          }}
        >
          value = {value}
        </code>
      </div>
    </div>
  );
}

import { ProgressBar } from '@refy-design/web';
import type { ComponentProps } from 'react';
export function Example() {
  const args: Pick<
    ComponentProps<typeof ProgressBar>,
    'value' | 'tone' | 'size' | 'indeterminate'
  > = { value: 49, tone: 'primary', size: 'md', indeterminate: true };
  return (
    <div style={{ width: 320 }}>
      <ProgressBar {...args} aria-label="Loading" />
    </div>
  );
}
